    const delta=(p)=>{if(!p.before)return p.now?`<span class="delta">new this period</span>`:"";const c=Math.round(100*(p.now-p.before)/p.before);return `<span class="delta ${c>=0?"up":"down"}">${c>=0?"▲":"▼"} ${Math.abs(c)}% vs previous ${days} days</span>`};
